"use client";

import { ChangeEvent, useMemo, useState } from "react";

type Invoice = {
  id: number;
  supplier: string;
  description: string;
  amount: number;
  date: string;
  work: string;
  status: "Classificada" | "A rever";
};

const works = [
  { name: "Casa do Pinhal", code: "OB-024", progress: 72, budget: 68400, extras: 3250, color: "terracotta" },
  { name: "Apartamento Baixa", code: "OB-023", progress: 38, budget: 41200, extras: 0, color: "lime" },
  { name: "Moradia do Lago", code: "OB-021", progress: 91, budget: 98700, extras: 8450, color: "blue" },
];

const initialInvoices: Invoice[] = [
  { id: 1, supplier: "Materiais Silva", description: "Cimento e argamassa", amount: 428.5, date: "18 ago 2026", work: "Casa do Pinhal", status: "Classificada" },
  { id: 2, supplier: "Alugueres Norte", description: "Aluguer de andaimes", amount: 875, date: "17 ago 2026", work: "Apartamento Baixa", status: "Classificada" },
  { id: 3, supplier: "Luz & Fio", description: "Material elétrico", amount: 193.2, date: "16 ago 2026", work: "Casa do Pinhal", status: "A rever" },
  { id: 4, supplier: "Pedra Forte", description: "Ladrilho exterior", amount: 1240, date: "14 ago 2026", work: "Moradia do Lago", status: "Classificada" },
];

const money = new Intl.NumberFormat("pt-PT", { style: "currency", currency: "EUR" });

export default function Home() {
  const [selectedWork, setSelectedWork] = useState("Todas as obras");
  const [invoices, setInvoices] = useState(initialInvoices);
  const [isUploading, setIsUploading] = useState(false);

  const visibleInvoices = useMemo(
    () => selectedWork === "Todas as obras" ? invoices : invoices.filter((invoice) => invoice.work === selectedWork),
    [invoices, selectedWork],
  );

  const totalSpent = invoices.reduce((total, invoice) => total + invoice.amount, 0);
  const totalBudget = works.reduce((total, work) => total + work.budget, 0);
  const totalExtras = works.reduce((total, work) => total + work.extras, 0);
  const availableBudget = totalBudget + totalExtras - totalSpent;

  function getWorkSpent(workName: string) {
    return invoices
      .filter((invoice) => invoice.work === workName)
      .reduce((total, invoice) => total + invoice.amount, 0);
  }

  function handleInvoiceUpload(event: ChangeEvent<HTMLInputElement>) {
    const file = event.target.files?.[0];
    if (!file) return;

    setIsUploading(true);
    window.setTimeout(() => {
      setInvoices((current) => [{
        id: Date.now(),
        supplier: file.name.replace(/\.[^/.]+$/, ""),
        description: "Fatura digitalizada",
        amount: 0,
        date: "Hoje",
        work: selectedWork === "Todas as obras" ? works[0].name : selectedWork,
        status: "A rever",
      }, ...current]);
      setIsUploading(false);
      event.target.value = "";
    }, 900);
  }

  return (
    <main className="dashboard-shell">
      <aside className="dashboard-sidebar">
        <div className="brand-lockup"><span className="dino-mark" aria-hidden="true">◒</span><span className="display-font text-xl font-bold">dino<span className="text-[var(--orange)]">.</span></span></div>
        <div className="sidebar-label">Área de trabalho</div>
        <nav className="sidebar-nav" aria-label="Navegação principal">
          <a className="nav-item nav-item-active" href="#resumo"><span>▦</span> Resumo</a>
          <a className="nav-item" href="#obras"><span>⌂</span> Obras <b>3</b></a>
          <a className="nav-item" href="#faturas"><span>▤</span> Faturas <b>{invoices.length}</b></a>
        </nav>
        <div className="sidebar-bottom"><span className="status-dot" /> Dados locais <span className="text-xs text-[var(--muted)]">v0.1</span></div>
      </aside>

      <section className="dashboard-content">
        <header className="dashboard-header">
          <div><p className="eyebrow">Terça-feira, 18 de agosto de 2026</p><h1 className="display-font dashboard-title">Bom dia, António.</h1></div>
          <div className="profile-chip"><span className="profile-avatar">AF</span><span className="hidden sm:block">António Ferreira</span><span aria-hidden="true">⌄</span></div>
        </header>

        <div className="dashboard-grid" id="resumo">
          <div className="summary-card summary-card-dark"><span className="card-kicker">Orçamento total</span><strong>{money.format(totalBudget)}</strong><span className="card-foot">Pedido pelo cliente</span></div>
          <div className="summary-card"><span className="card-kicker">Extras aprovados</span><strong>{money.format(totalExtras)}</strong><span className="card-foot">Orçamento disponível: {money.format(availableBudget)}</span></div>
          <div className="summary-card"><span className="card-kicker">Faturas por rever</span><strong>{invoices.filter((invoice) => invoice.status === "A rever").length}</strong><span className="card-foot">Precisam da tua atenção</span></div>
          <div className="upload-card"><div><span className="card-kicker">Entrada rápida</span><h2 className="display-font text-2xl font-bold">Digitalizar fatura</h2><p>Carrega uma foto ou PDF. O Dino prepara os dados para a obra certa.</p></div><label className="upload-button"><span>{isUploading ? "A ler..." : "Adicionar fatura"}</span><span className="text-xl">＋</span><input type="file" accept="image/*,.pdf" onChange={handleInvoiceUpload} disabled={isUploading} /></label></div>
        </div>

        <section className="content-section" id="obras">
          <div className="section-heading"><div><p className="eyebrow">A acompanhar</p><h2 className="display-font section-title">As tuas obras</h2></div><button className="text-button">Ver todas <span>→</span></button></div>
          <div className="works-grid">{works.map((work) => { const spent = getWorkSpent(work.name); return <article className="work-card" key={work.code}><div className={`work-color work-color-${work.color}`}><span>{work.code}</span><span>↗</span></div><div className="work-card-body"><div className="flex items-start justify-between gap-3"><h3>{work.name}</h3><span className="work-progress">{work.progress}%</span></div><div className="progress-track"><span style={{ width: `${work.progress}%` }} /></div><div className="work-finance"><div><span>Orçamento</span><strong>{money.format(work.budget)}</strong></div><div><span>Extras</span><strong className={work.extras ? "extra-value" : ""}>{work.extras ? `+ ${money.format(work.extras)}` : "—"}</strong></div></div><div className="work-meta"><span>Gasto registado</span><strong>{money.format(spent)}</strong></div></div></article>; })}</div>
        </section>

        <section className="content-section invoice-section" id="faturas">
          <div className="section-heading"><div><p className="eyebrow">Contabilidade sem papéis</p><h2 className="display-font section-title">Faturas recentes</h2></div><select className="work-filter" value={selectedWork} onChange={(event) => setSelectedWork(event.target.value)}><option>Todas as obras</option>{works.map((work) => <option key={work.name}>{work.name}</option>)}</select></div>
          <div className="invoice-table-wrap"><table className="invoice-table"><thead><tr><th>Fornecedor</th><th>Descrição</th><th>Obra</th><th>Data</th><th className="text-right">Valor</th><th>Estado</th></tr></thead><tbody>{visibleInvoices.map((invoice) => <tr key={invoice.id}><td className="font-bold">{invoice.supplier}</td><td>{invoice.description}</td><td>{invoice.work}</td><td>{invoice.date}</td><td className="text-right font-bold">{invoice.amount ? money.format(invoice.amount) : "Por preencher"}</td><td><span className={`invoice-status ${invoice.status === "A rever" ? "invoice-status-review" : ""}`}>{invoice.status}</span></td></tr>)}</tbody></table></div>
        </section>
      </section>
    </main>
  );
}
